import pytest

from app.errors import ValidationError
from app.features.discounts import apply_discount


def test_example_from_spec():
    assert apply_discount("19.99", 10) == "$18.00"


def test_zero_percent_keeps_price():
    assert apply_discount("19.99", 0) == "$19.99"


def test_full_discount_is_free():
    assert apply_discount("19.99", 100) == "$0.00"


def test_rounds_discount_down():
    # 1000 * 33 // 100 = 330 discount -> 670 left
    assert apply_discount("10.00", 33) == "$6.70"


def test_accepts_plain_and_single_decimal_prices():
    assert apply_discount("20", 50) == "$10.00"
    assert apply_discount("20.5", 10) == "$18.45"


@pytest.mark.parametrize("percent", [-1, 101, 1000])
def test_percent_out_of_range_raises(percent):
    with pytest.raises(ValidationError):
        apply_discount("19.99", percent)


@pytest.mark.parametrize("percent", [10.0, "10", None, True])
def test_percent_not_int_raises(percent):
    with pytest.raises(ValidationError):
        apply_discount("19.99", percent)


@pytest.mark.parametrize("price", ["", "abc", "1.234", "-5.00", "1,000.00", "12.3.4"])
def test_invalid_price_raises(price):
    with pytest.raises(ValidationError):
        apply_discount(price, 10)

